SELECT count(*) FROM R AS e0, R AS e1, R AS e2, R AS e3, R AS e4, R AS e5, R AS e6, R AS e7, R AS e8, R AS e9 WHERE e2.col0 = e0.col1 AND e3.col0 = e2.col1 AND e4.col0 = e3.col1 AND e4.col1 = e1.col0 AND e5.col0 = e1.col0 AND e5.col1 = e0.col0 AND e6.col0 = e0.col0 AND e6.col1 = e1.col1 AND e7.col0 = e0.col1 AND e7.col1 = e1.col1 AND e8.col0 = e2.col1 AND e8.col1 = e1.col1 AND e9.col0 = e3.col1 AND e9.col1 = e1.col1;